"""Build source-led medicinal chemistry pages using the portfolio's academic components."""
from pathlib import Path
import json
from render_research import document,scientific_figure
R=Path(__file__).resolve().parents[1]
inv=json.loads((R/'data/medchem-figure-inventory.json').read_text())
def fig(name,caption,minw=600):
 f=next(f for f in inv if f['file']==f'medchem-assets/{name}.png')
 return scientific_figure(dict(type='image',src=f['file'],width=f['width'],height=f['height'],min_width=minw,alt=caption,caption=caption))
def doc(title,intro,body,kind='medchem-detail'):
 return document(title,intro,body,'medchem-page '+kind).replace('href="nanopore.html" aria-current="page"','href="research.html" aria-current="page"').replace('<script src="research.js"','<link rel="stylesheet" href="medchem.css?v=medchem-1"><script src="research.js"').replace('<a href="nanopore.html">Research overview</a>','<a href="research.html">Research areas</a>')
def area_nav():return '<nav class="area-nav wrap" aria-label="Research areas"><a href="nanopore.html">Nanopore-Based Molecular Sensing</a><a href="medchem.html" aria-current="page">Medicinal Chemistry & Drug Discovery</a></nav>'
intro='My research interests lie in understanding how molecular structure and chemical interactions influence biological activity, and how these relationships can guide the design of potential therapeutic compounds. Through computational molecular modelling and experimental organic synthesis, I have explored different approaches to rational drug design and molecular optimisation.'
t1='Structure-Based Design of SARS-CoV-2 Main Protease Inhibitors'
t2='SAR-Guided Design and Synthesis of Antileishmanial Acyl Urea Analogues'
d1='This project explored the structure-guided design of non-covalent SARS-CoV-2 main protease inhibitors. Molecular docking and protein–ligand interaction analysis were used to evaluate candidate scaffolds and guide the design of three new analogues. A synthetic route and enzyme inhibition assay were subsequently proposed to support future experimental evaluation.'
d2='Exploring structure–activity relationships in an antileishmanial acyl urea series, this project investigated how molecular modifications could influence physicochemical properties and potential biological activity. Two designed analogues were synthesised through a two-step reaction sequence and characterised using spectroscopic and analytical techniques.'
pose=fig('mpro-pose','Predicted binding pose of Analogue 2. Docking report, p. 5, Figure 6 (3D panel). Computational model; not an experimentally determined analogue complex.',0)
design=fig('acyl-design','Lead compound and proposed F1/F2 designs. Laboratory report, p. 2, Figure 1. F2 here is the proposed para-chloro structure; the synthesised F2 was meta-chloro.',600)
route=fig('acyl-synthesis','Experimentally used two-step route to F1 and F2 (m-Cl). Laboratory report, p. 3, Scheme 1. The isolated samples retained impurities; biological activity was not measured.',850)
body=area_nav()+f'<header class="overview-heading wrap"><a class="back-link" href="research.html">← Research areas</a><p class="eyebrow">RESEARCH / IMPERIAL COLLEGE LONDON</p><h1>Medicinal Chemistry &amp; Drug Discovery</h1><p class="research-focus">{intro}</p></header><div class="wrap"><article class="medchem-project computational"><div><p class="eyebrow">01 / COMPUTATIONAL MOLECULAR DESIGN</p><h2>{t1}</h2><p>{d1}</p><p class="project-status">Computational modelling completed; synthesis and biological evaluation proposed.</p><a class="explore-research" href="mpro-inhibitors.html">Explore Research →</a></div>{pose}</article><article class="medchem-project experimental">{design}<div><p class="eyebrow">02 / EXPERIMENTAL MEDICINAL CHEMISTRY</p><h2>{t2}</h2><p>{d2}</p><p class="project-status">F1 and meta-chloro F2 synthesised; biological activity untested.</p><a class="explore-research" href="antileishmanial-acyl-ureas.html">Explore Research →</a></div><div class="wide-scheme">{route}</div></article></div>'
(R/'medchem.html').write_text(doc('Medicinal Chemistry & Drug Discovery',intro,body,'medchem-overview'))
def section(id,title,text,figures=''):
 return f'<section class="research-topic" id="{id}"><h2>{title}</h2>{text}{figures}</section>'
def p(s):return '<p>'+s+'</p>'
def details(title,kicker,intro,sections,source):
 nav=''.join(f'<a href="#{i}">{t}</a>' for i,t,_,_ in sections)
 content=''.join(section(*s) for s in sections)
 return area_nav()+f'<header class="detail-heading wrap"><a class="back-link" href="medchem.html">← Back to Medicinal Chemistry</a><p class="eyebrow">{kicker}</p><h1>{title}</h1><p>{intro}</p></header><div class="research-layout wrap"><aside class="research-contents"><p class="eyebrow">CONTENTS</p><nav aria-label="Research contents">{nav}<a href="#sources">Sources & figure credits</a></nav></aside><div class="research-article">{content}<section class="research-topic sources" id="sources"><h2>Sources & figure credits</h2>{source}</section><nav class="detail-return"><a href="medchem.html">← Back to Medicinal Chemistry</a></nav></div></div>'
mpro=[
('motivation','Scientific motivation',p('SARS-CoV-2 main protease (Mpro) processes viral polyproteins and is a target for antiviral inhibitor design. This project examined non-covalent recognition: how a scaffold occupies the binding pocket and presents groups capable of favourable interactions.'),''),
('modelling','Structure-based molecular modelling',p('The receptor was based on PDB 7S3K, containing Mpro bound to Z1530718726. PyMOL was used to inspect the crystal geometry. MOE QuickPrep added hydrogens, assigned protonation states and applied local minimisation before redocking and interaction analysis.')+p('The co-crystallised ligand provided a reference for checking pose recovery. Docking used London dG placement scoring followed by GBVI/WSA rescoring and induced-fit refinement. These are docking calculations; molecular dynamics was proposed as further work.'),fig('mpro-redocking','Co-crystal ligand (grey) and MOE-redocked pose (cyan). Docking report, p. 2, Figure 4. The overlay compares model geometry; it does not validate biological activity.',500)),
('ligands','Ligand evaluation',p('Manidipine, Ligand 1, Ligand 2 and the X0104 fragment were compared for subsite occupation, polar contacts, hydrophobic burial and orientation. The report describes Ligand 1 as a compact S1-binding scaffold with a His163 hydrogen-bond contact and His41 contact, suitable for a fragment-growing exercise.')+p('Ligand 2 occupied a broader region of the pocket, while the bulky Manidipine pose illustrated why hydrophobic burial can favour a score without providing an equally convincing recognition pattern. Residues considered across the models included His163, Glu166, His41, Cys145 and Met165. These are model-based comparisons; literature activity values discussed in the report were not assays performed in this project.'),''),
('optimisation','Structure-guided molecular optimisation',p('Three analogues were designed from Ligand 1. Analogue 1 replaced an ester with an amide and introduced a heteroaryl extension. Analogue 2 expanded aromatic substitution to explore additional pocket space. Analogue 3 used a more directed terminal arrangement to explore contacts in the extended binding region.')+p('The original structures below show the designs, while the selected Analogue 2 interaction map illustrates the predicted geometry. These annotations are computational hypotheses, not experimentally established interaction energies or inhibition mechanisms.'),fig('mpro-designs','The three designed analogues. Docking report, p. 1, Figure 1, panel e. Original chemical structures and labels retained.',650)+fig('mpro-interactions','Selected docking-derived interaction map for Analogue 2. Docking report, p. 5, Figure 6. Labels and interaction annotations are reproduced from the source model.',550)+pose),
('limitations','Beyond docking scores',p('Docking scores were treated as supporting evidence alongside pose inspection. A larger hydrophobic ligand may score well because of buried surface area; this does not establish affinity or selectivity. Molecular flexibility, retained-water orientation and the scoring function can alter the predicted pose and ranking.')+p('The report observed sensitivity to small molecular changes. Experimental synthesis, biochemical inhibition measurements and additional structural evidence would be required to test the design hypotheses.'),''),
('synthesis','Proposed synthetic route',p('For Analogue 3, the report proposed reductive amination of an amine and aldehyde using sodium triacetoxyborohydride, followed by T3P-promoted amide coupling with the carboxylic-acid component. The original scheme retains the source reagents, conditions and molecular structures.')+p('<strong>Status:</strong> synthetic planning only. This project did not establish that the designed Mpro analogue was synthesised or characterised.'),fig('mpro-proposed-route','Proposed synthetic route to Analogue 3. Docking report, p. 6, Scheme 1. Reductive amination followed by T3P-promoted amidation; not experimentally completed.',700)),
('evaluation','Proposed biological evaluation',p('A FRET-based Mpro inhibition assay was proposed. Cleavage of a labelled peptide separates fluorophore and quencher, increasing fluorescence; an inhibitor would reduce the rate of signal increase. A concentration series and appropriate enzyme, substrate and inhibitor controls would support interpretation.')+p('No assay outcomes or analogue IC₅₀ values were generated in this project.'),''),
('perspective','Research perspective',p('The project connected pose analysis to specific molecular modifications and an experimentally testable plan. The next decision would depend on whether accessible synthetic products reproduce the predicted recognition pattern and inhibit Mpro in a controlled assay.'),'')]
source=p('Yihan Li, <cite>Evaluation of SARS-CoV-2 Main Protease Inhibitors Using Molecular Docking</cite>, supplied academic report. Figure crops retain the original scientific geometry and labels; report-template furniture is excluded. The report is an academic project, not a published journal article.')+p('<a href="https://www.rcsb.org/structure/7S3K">RCSB PDB 7S3K ↗</a> — reference crystal structure. Associated primary study: <a href="https://doi.org/10.1021/acsptsci.2c00026">Glaser et al., Hit Expansion of a Noncovalent SARS-CoV-2 Main Protease Inhibitor (2022) ↗</a>. Published experiments are background, not personal project results.')
(R/'mpro-inhibitors.html').write_text(doc(t1,d1,details(t1,'COMPUTATIONAL PROJECT / MODELLING COMPLETED · SYNTHESIS & ASSAY PROPOSED','Molecular docking and structure-guided analogue design, with proposed routes to experimental validation.',mpro,source)))
acyl=[
('background','Scientific background',p('Leishmaniasis is caused by Leishmania parasites. The project investigated an acyl urea series as a starting point for potential antiparasitic compounds, using existing series data to formulate modifications for experimental synthesis.'),''),
('sar','Structure–activity relationship analysis',p('The lead was DNDi0003974028 in the P7 series. The proposal and laboratory report considered aromatic substitution and lipophilicity as variables that might influence molecular exposure and biological activity. Adding phenyl groups and a chloro substituent was intended to test these hypotheses while retaining the acyl urea core.')+p('Greater lipophilicity is not automatically beneficial: permeability, solubility and selectivity must be assessed together. No improved antileishmanial activity was demonstrated for the synthesised analogues.'),design),
('design','Proposed and synthesised structures',p('F1 and a para-chloro F2 were considered in the original design. The available amine used for synthesis instead carried meta-chloro substitution, giving F2 (m-Cl). The experimental product is therefore the meta-chloro derivative, rather than the para-chloro design shown above.')+p('An n-propyl analogue, G1, was considered as an additional design hypothesis but was not prioritised for synthesis.'),fig('acyl-meta-product','Actually synthesised F2: meta-chloro analogue. Laboratory report, p. 2, Figure 2. Compare with proposed para-chloro F2 in Figure 1 above.',0)),
('synthesis','Completed two-step synthesis',p('<strong>Step 1 — nucleophilic acyl substitution.</strong> Benzylurea was acylated with 3-chloropropanoyl chloride to form the acyl urea intermediate. The laboratory route used anhydrous THF, initially at 0 °C under nitrogen.')+p('<strong>Step 2 — nucleophilic substitution.</strong> The chloroalkyl intermediate reacted with N-methylbenzylamine or the corresponding meta-chloro amine in DCM with triethylamine to produce F1 or F2 (m-Cl). The laboratory report, rather than the earlier proposal, is the source for the experimentally used route.'),route),
('mechanisms','Reaction mechanisms',p('Acylation involves attack of the urea nitrogen on the acid chloride, formation of a tetrahedral intermediate and elimination of chloride. The second transformation forms a C–N bond by substitution at the chloroalkyl carbon; triethylamine supports the reaction by accepting a proton.')+p('The original report’s mechanism drawings are reproduced below as proposed chemical explanations, not as experimentally observed intermediates.'),fig('acyl-acylation-mechanism','Source-proposed acylation mechanism. Laboratory report, p. 3, Figure 4. Original bonds, charges and curved arrows retained.',850)+fig('acyl-substitution-mechanism','Source-proposed substitution mechanisms for F1 and F2 (m-Cl). Laboratory report, p. 4, Figure 5. Original structures and arrows retained.',850)),
('challenges','Experimental challenges',p('TLC showed residual benzylurea after overnight acylation. The report discusses limited solubility and possible acid-chloride hydrolysis as explanations, rather than confirmed causes. Urea–silica interactions contributed to low TLC mobility; amine-containing samples also showed tailing.')+p('Dry loading was used when the intermediate dissolved poorly in the chromatography eluent. Adding a small amount of triethylamine to the TLC eluent improved spot definition. HPLC revealed additional components after purification; their identities were not established.'),''),
('characterisation','Purification and characterisation',p('Products were isolated after work-up and silica-gel chromatography. ¹H NMR supported the expected aromatic, benzylic, linker and acyl urea environments. FTIR supported N–H and carbonyl functionality, and HRMS supported the expected molecular compositions.')+p('Analytical HPLC at 254 nm assessed the isolated samples and showed residual impurities. The report gives major-peak area percentages of approximately 81.7% for F1 and 72.7% for F2; these are chromatographic area measurements, not proof of absolute chemical purity. No high-purity or biological-performance claim is made.'),''),
('perspective','Research perspective',p('The work linked SAR hypotheses to synthetic feasibility and evidence from complementary analytical methods. Further purification and biological testing would be needed before relating the molecular changes to antiparasitic activity or selectivity.'),'')]
source=p('Yihan Li, <cite>Synthesis and Analysis of Acyl Urea Analogues for SAR Investigation in the P7 Series</cite>, supplied laboratory report (<cite>cmc lab report-3.pdf</cite>), pp. 1–8 and supporting information, pp. 8–13; and the supplied <cite>medchem proposal.pdf</cite>, particularly design and planning on pp. 1–3.')+p('The laboratory report governs the actual route, meta-chloro substitution and analytical observations. Earlier proposal conditions and proposed structures are not substituted for completed experiments. Original figures are reproduced as requested; the source reports are not presented as published journal articles.')
(R/'antileishmanial-acyl-ureas.html').write_text(doc(t2,d2,details(t2,'EXPERIMENTAL PROJECT / SYNTHESIS & CHARACTERISATION','SAR-guided molecular design, two-step synthesis and analytical assessment; biological activity remains to be tested.',acyl,source)))
# Simple research-area navigation rather than replacing existing scientific pages.
hub=area_nav().replace(' aria-current="page"','')+'''<header class="overview-heading wrap"><a class="back-link" href="index.html#research">← Portfolio</a><p class="eyebrow">RESEARCH</p><h1>Research areas</h1></header><div class="wrap research-areas"><article><p class="eyebrow">01 / MOLECULAR SENSING</p><h2>Nanopore-Based Molecular Sensing</h2><p>Molecular recognition, quantitative readout and exploratory signal fingerprinting.</p><a href="nanopore.html">Explore nanopore research →</a></article><article><p class="eyebrow">02 / MOLECULAR DESIGN</p><h2>Medicinal Chemistry &amp; Drug Discovery</h2><p>Computational inhibitor design and experimental synthesis of acyl urea analogues.</p><a href="medchem.html">Explore medicinal chemistry →</a></article><article><p class="eyebrow">03 / PHOSPHORUS FUNCTIONALIZATION</p><h2>Computational and Experimental Investigation of Base-Mediated White Phosphorus Functionalization</h2><p>Atom-labelled connectivity hypotheses and complementary computational and experimental investigation.</p><a href="white-phosphorus.html">Explore Research 03 →</a></article></div>'''
(R/'research.html').write_text(doc('Research areas','Nanopore sensing and medicinal chemistry research.',hub,'research-hub'))
print('Built MedChem overview, two detail pages and research-area index.')
